# apply_restart_and_run.py — scrapes lap-times, adds restart features, and
# compares matchup LL vs. previous best (0.6180).
import base64, subprocess, sys, pathlib

FILES = {
    'src/scrape/nascar_laptimes.py': '',
    'src/cli/backfill_laptimes.py': '',
    'src/features/restart.py': '',
    'src/features/build_features.py': '',
    'src/models/gbm_ranker.py': '',
    'src/eval/backtest_gbm_walkforward.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    laptimes_path = pathlib.Path("data/processed/laptimes.parquet")
    force = "--refresh" in sys.argv
    if not laptimes_path.exists() or force:
        print("\n=== backfilling lap-times (~3 min) ===")
        subprocess.run([sys.executable, "-m", "src.cli.backfill_laptimes"], check=True)
    else:
        print(f"\nlaptimes.parquet already exists ({laptimes_path.stat().st_size // (1024*1024)} MB); "
              "pass --refresh to re-fetch")

    import pandas as pd
    from src.eval.backtest_gbm_walkforward import backtest_gbm_walkforward, summarize_wf

    TIGHT_REG = {"num_leaves": 31, "min_data_in_leaf": 25, "lambda_l2": 2.0}
    ALPHA = 0.85

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")
    loopstats = pd.read_parquet("data/processed/loopstats.parquet")
    laptimes = pd.read_parquet("data/processed/laptimes.parquet")
    print(f"\nlaptimes rows: {len(laptimes):,}  races: {laptimes['race_id_short'].nunique()}")

    results = {}
    for name, use_laptimes in [
        ("A. no-restart (baseline 0.6180)", False),
        ("B. + restart features",           True),
    ]:
        print(f"\n--- {name} ---")
        out = backtest_gbm_walkforward(
            races, entries, sessions, loopstats,
            laptimes=(laptimes if use_laptimes else None),
            initial_train_races=36, retrain_every_n=10,
            calib_window=25, recalibrate_every_n=10,
            ensemble_alpha=ALPHA, n_samples=3000,
            gbm_fit_kwargs=TIGHT_REG,
        )
        by_type = summarize_wf(out["metrics"])
        print(by_type.round(4).to_string())
        results[name] = by_type.loc["ALL"]

        if use_laptimes:
            try:
                booster = out["model"].booster
                imp = pd.DataFrame({
                    "feature": booster.feature_name(),
                    "gain": booster.feature_importance(importance_type="gain"),
                }).sort_values("gain", ascending=False)
                print("\nRestart feature ranks (by gain):")
                for f in ["restart_gain_5", "restart_gain_10", "restart_count_10"]:
                    row = imp[imp["feature"] == f]
                    if len(row):
                        rank = imp.reset_index().index[imp.reset_index()["feature"] == f].tolist()
                        rank_val = rank[0] + 1 if rank else "?"
                        print(f"  {f}: gain={row['gain'].iloc[0]:.1f}, rank #{rank_val}")
            except Exception as e:
                print(f"(feat importance skipped: {e})")

    print("\n=== SUMMARY ===")
    df = pd.DataFrame({k: v[["winner_logloss","matchup_logloss","spearman_rho","top5_accuracy"]]
                       for k, v in results.items()}).T
    df.index.name = "config"
    print(df.round(4).to_string())

if __name__ == "__main__":
    main()
